from __future__ import annotations
from dataclasses import dataclass
from typing import TypeAlias
@dataclass(frozen=True)
class Leaf: named: bool = False
@dataclass(frozen=True)
class Unary: child: "Tree"
@dataclass(frozen=True)
class Binary: left: "Tree"; right: "Tree"
Tree: TypeAlias = Leaf | Unary | Binary

def statistics(t: Tree) -> tuple[int, int, int]:
    if isinstance(t, Leaf): return (1, 0, int(t.named))
    if isinstance(t, Unary):
        n, d, m = statistics(t.child); return (n + 1, d + 1, m)
    nl, dl, ml = statistics(t.left); nr, dr, mr = statistics(t.right)
    return (1 + nl + nr, 1 + max(dl, dr), ml + mr)

def audited_cost(t: Tree) -> int: return sum(statistics(t))

from __future__ import annotations
from dataclasses import dataclass
from typing import TypeAlias
@dataclass(frozen=True)
class Hyp: formula: str
@dataclass(frozen=True)
class Named: name: str; formula: str
@dataclass(frozen=True)
class Restate: formula: str; child: "Tree"
@dataclass(frozen=True)
class MP: formula: str; left: "Tree"; right: "Tree"
Tree: TypeAlias = Hyp | Named | Restate | MP

def conclusion(t: Tree) -> str:
    return t.formula

def strip(t: Tree) -> Tree:
    return t.child if isinstance(t, Restate) else t

def normalize(t: Tree) -> Tree:
    if isinstance(t, Hyp): return t
    if isinstance(t, Named): return Hyp(t.formula)
    if isinstance(t, MP): return MP(t.formula, strip(normalize(t.left)), strip(normalize(t.right)))
    child = normalize(t.child)
    return child if conclusion(child) == t.formula else Restate(t.formula, child)

from __future__ import annotations
from typing import Sequence

def suffix_start(xs: Sequence[object]) -> int:
    if not xs: raise ValueError("empty sequence")
    i = len(xs) - 1
    while i > 0 and xs[i - 1] == xs[-1]: i -= 1
    return i

def synchronized_stage(costs: Sequence[int], ideals: Sequence[frozenset[str]]) -> int:
    if len(costs) != len(ideals) or not costs: raise ValueError("incompatible traces")
    if any(b > a for a, b in zip(costs, costs[1:])): raise ValueError("costs must descend")
    if any(not a <= b for a, b in zip(ideals, ideals[1:])): raise ValueError("ideals must ascend")
    return max(suffix_start(costs), suffix_start(ideals))

