class Restate:
    formula: str
    child: "Tree"


Tree: TypeAlias = Hyp | Named | MP | Restate


def conclusion(tree: Tree) -> str:
    """Return the formula recorded at the root."""
    if isinstance(tree, (Hyp, Named)):
        return tree.formula
    if isinstance(tree, MP):
        return tree.conclusion
    return tree.formula


